def ConvertScoreToGrade(score):
    if (score >= 70):
        return 'Distinction'
    elif (score >= 60):
        return 'Merit'
    elif (score >= 40):
        return 'Pass'
    else:
        return 'Fail'
print(ConvertScoreToGrade(85))
